// Regenerates the committed image fixtures (story 12). Run: node tests/fixtures/images/generate.mjs
// PNG, JPEG and WebP are encoded by Chromium's canvas; the GIF, SVG and PDF are written by hand.
// The 10 MB boundary files are generated by the tests themselves (tests/fixtures/image-files.ts).
import { writeFileSync } from 'node:fs';
import { chromium } from '@playwright/test';

const dir = new URL('./', import.meta.url);
const write = (name, bytes) => writeFileSync(new URL(name, dir), bytes);

const browser = await chromium.launch();
const page = await browser.newPage();
async function encode(width, height, type, quality, style) {
  const b64 = await page.evaluate(
    async ({ width, height, type, quality, style }) => {
      const c = new OffscreenCanvas(width, height);
      const g = c.getContext('2d');
      const grad = g.createLinearGradient(0, 0, width, height);
      grad.addColorStop(0, style === 'photo' ? '#2e7d32' : '#e3f2fd');
      grad.addColorStop(1, style === 'photo' ? '#f9a825' : '#90caf9');
      g.fillStyle = grad;
      g.fillRect(0, 0, width, height);
      if (style === 'photo') {
        // Noise so the JPEG is photo-sized (a few MB), not a tiny gradient.
        const img = g.getImageData(0, 0, width, height);
        let seed = 7;
        for (let i = 0; i < img.data.length; i += 4) {
          seed = (seed * 1103515245 + 12345) & 0x7fffffff;
          const n = (seed % 64) - 32;
          img.data[i] += n;
          img.data[i + 1] += n;
          img.data[i + 2] += n;
        }
        g.putImageData(img, 0, 0);
      } else {
        g.fillStyle = '#1e88e5';
        g.fillRect(0, 0, width, Math.round(height / 12));
        g.fillStyle = '#ffffff';
        for (let i = 0; i < 6; i++) g.fillRect(40 + i * 220, 140, 180, 120);
      }
      const blob = await c.convertToBlob({ type, quality });
      const bytes = new Uint8Array(await blob.arrayBuffer());
      let s = '';
      for (const b of bytes) s += String.fromCharCode(b);
      return btoa(s);
    },
    { width, height, type, quality, style },
  );
  return Buffer.from(b64, 'base64');
}

const png = await encode(1440, 900, 'image/png', undefined, 'screenshot');
write('screenshot.png', png);
write('screenshot-2.png', await encode(1200, 600, 'image/png', undefined, 'screenshot'));
write('screenshot-3.png', await encode(600, 900, 'image/png', undefined, 'screenshot'));
write('photo.jpg', await encode(4032, 3024, 'image/jpeg', 0.9, 'photo'));
write('sample.webp', await encode(640, 480, 'image/webp', 0.8, 'screenshot'));
await browser.close();

// Truncated PNG: valid signature and header, missing image data.
write('corrupt.png', png.subarray(0, 64));

// Animated GIF: 40x30, two full frames (red, then blue), looping. The image data
// is LZW with a clear code before every pair of pixels, so codes stay 3 bits wide.
function gifFrameData(width, height, colour) {
  const codes = [];
  for (let i = 0; i < width * height; i += 2) codes.push(4, colour, colour); // clear, pixel, pixel
  codes.push(5); // end of information
  const bytes = [];
  let acc = 0;
  let bits = 0;
  for (const c of codes) {
    acc |= c << bits;
    bits += 3;
    while (bits >= 8) {
      bytes.push(acc & 0xff);
      acc >>= 8;
      bits -= 8;
    }
  }
  if (bits > 0) bytes.push(acc & 0xff);
  const out = [0x02]; // LZW minimum code size
  for (let i = 0; i < bytes.length; i += 255) {
    const block = bytes.slice(i, i + 255);
    out.push(block.length, ...block);
  }
  out.push(0x00);
  return out;
}
const frame = (colour) => [
  0x21, 0xf9, 0x04, 0x00, 0x32, 0x00, 0x00, 0x00, // 0.5 s delay
  0x2c, 0, 0, 0, 0, 40, 0, 30, 0, 0x00, ...gifFrameData(40, 30, colour),
];
const gif = Buffer.from([
  ...Buffer.from('GIF89a'),
  40, 0, 30, 0, 0xf1, 0, 0, // screen 40x30, global colour table of 4 entries
  0xe5, 0x39, 0x35, 0x1e, 0x88, 0xe5, 0xff, 0xff, 0xff, 0x00, 0x00, 0x00,
  0x21, 0xff, 0x0b, ...Buffer.from('NETSCAPE2.0'), 0x03, 0x01, 0x00, 0x00, 0x00, // loop forever
  ...frame(0),
  ...frame(1),
  0x3b,
]);
write('animated.gif', gif);

write(
  'script.svg',
  '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><script>alert(1)</script><rect width="100" height="100"/></svg>\n',
);
write(
  'document-renamed.png',
  '%PDF-1.4\n1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n2 0 obj << /Type /Pages /Kids [] /Count 0 >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF\n',
);
